Translate the following GNU C++11 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <string>
#include <algorithm>
using namespace std;

int n, t;
string a[30], b[30];
int dist1[30][30], dist2[30][30];
int dx[] = {0,0,-1,1};
int dy[] = {1,-1,0,0};

struct Edge {
    int to, rev, cap;
};
vector<Edge> g[1000];
int level[1000], it[1000];

void add_edge(int from, int to, int cap) {
    g[from].push_back({to, (int)g[to].size(), cap});
    g[to].push_back({from, (int)g[from].size()-1, 0});
}

bool ok(int x, int y) { return x>=0 && x<n && y>=0 && y<n; }

void bfs1(int sx, int sy) {
    for (int i=0;i<30;i++) for (int j=0;j<30;j++) dist1[i][j]=1e9;
    queue<pair<int,int>> q;
    q.push({sx,sy});
    dist1[sx][sy]=0;
    while (!q.empty()) {
        int x=q.front().first, y=q.front().second; q.pop();
        for (int i=0;i<4;i++) {
            int nx=x+dx[i], ny=y+dy[i];
            if (ok(nx,ny) && dist1[nx][ny]>=1e9 && b[nx][ny]!='Y') {
                dist1[nx][ny]=dist1[x][y]+1;
                q.push({nx,ny});
            }
        }
    }
}

bool bfs(int s, int t) {
    memset(level,-1,sizeof(level));
    queue<int> q;
    q.push(s);
    level[s]=0;
    while (!q.empty()) {
        int v=q.front(); q.pop();
        for (Edge &e : g[v]) {
            if (level[e.to]==-1 && e.cap>0) {
                level[e.to]=level[v]+1;
                q.push(e.to);
            }
        }
    }
    return level[t]!=-1;
}

int dfs(int v, int t, int f) {
    if (v==t) return f;
    for (int &i=it[v]; i<(int)g[v].size(); i++) {
        Edge &e=g[v][i];
        if (level[e.to]==level[v]+1 && e.cap>0) {
            int d=dfs(e.to,t,min(f,e.cap));
            if (d>0) {
                e.cap-=d;
                g[e.to][e.rev].cap+=d;
                return d;
            }
        }
    }
    return 0;
}

int max_flow(int s, int t) {
    int flow=0;
    while (bfs(s,t)) {
        memset(it,0,sizeof(it));
        while (int f=dfs(s,t,1e9)) flow+=f;
    }
    return flow;
}

void bfs2(int sx, int sy) {
    for (int i=0;i<30;i++) for (int j=0;j<30;j++) dist2[i][j]=1e9;
    queue<pair<int,int>> q;
    q.push({sx,sy});
    dist2[sx][sy]=0;
    while (!q.empty()) {
        int x=q.front().first, y=q.front().second; q.pop();
        if (dist2[x][y]>=dist1[x][y]) continue;
        for (int i=0;i<4;i++) {
            int nx=x+dx[i], ny=y+dy[i];
            if (ok(nx,ny) && dist2[nx][ny]>=1e9 && a[nx][ny]!='Y' && dist2[x][y]+1<=dist1[nx][ny]) {
                dist2[nx][ny]=dist2[x][y]+1;
                q.push({nx,ny});
            }
        }
    }
}

int main() {
    cin>>n>>t;
    for (int i=0;i<n;i++) cin>>a[i];
    int wx, wy;
    for (int i=0;i<n;i++) {
        cin>>b[i];
        for (int j=0;j<n;j++) {
            if (b[i][j]=='Z') {
                b[i][j]=a[i][j]='Y';
                wx=i; wy=j;
            }
        }
    }
    bfs1(wx,wy);
    int source=0, sink=2*n*n+1;
    for (int i=0;i<n;i++) {
        for (int j=0;j<n;j++) {
            if (a[i][j]=='Y') continue;
            int what=i*n+j+1;
            int what2=n*n+i*n+j+1;
            add_edge(source,what,a[i][j]-'0');
            add_edge(what2,sink,b[i][j]-'0');
            bfs2(i,j);
            for (int x=0;x<n;x++) {
                for (int y=0;y<n;y++) {
                    if (b[x][y]=='Y' || dist2[x][y]>t) continue;
                    add_edge(what,n*n+x*n+y+1,a[i][j]-'0');
                }
            }
        }
    }
    n=2*n*n+5;
    cout<<max_flow(source,sink)<<endl;
    return 0;
}
